<?php

namespace Splicewire\Beam\Docs\PhpApi;

use Illuminate\Contracts\Auth\Authenticatable;
use Illuminate\Http\Request;
use Splicewire\Beam\Docs\Data\PhpApiIndexData;
use Splicewire\Beam\Docs\Data\PhpApiIndexInputData;
use Splicewire\Beam\Docs\Http\PhpApiReadGate;
use Splicewire\Beam\Particle\Attributes\ParticleOp;
use Splicewire\Beam\Particle\OperationKind;
use Splicewire\Beam\Particle\Subject\NoSubject;
use Splicewire\Beam\Routing\HttpMethod;

/**
 * `beam-docs.php-api-index` (php-api-reference slice 2), generated by `splicewire:beam:make:particle-op` and moved into
 * the package. Mounted at `GET beam/docs/php-api-index` beside `docs.search` (`web` + `DocsReadAccess` + a throttle),
 * behind {@see PhpApiReadGate}.
 *
 * `ability: false` is declared, not omitted: the authorization is the seeded PHP API page's own gate
 * ({@see PhpApiSurface}), checked by the route middleware and again here, so the data is readable exactly when the page
 * is. `affordance: false`: a docs read, never a framed action. The response is the generated index only
 * ({@see PhpApiArtifact::index()}); nothing is generated or parsed on the request.
 */
#[ParticleOp(
    resource: 'beam-docs',
    name: 'php-api-index',
    summary: 'The generated PHP API reference index: packages and their published symbols.',
    kind: OperationKind::Read,
    ability: false,
    affordance: false,
    input: PhpApiIndexInputData::class,
    output: PhpApiIndexData::class,
    subject: NoSubject::class,
    method: HttpMethod::Get,
)]
class PhpApiIndexOp
{
    public static function handle(mixed $subject, Request $request, mixed $actor): PhpApiIndexData
    {
        abort_unless(app(PhpApiSurface::class)->readable($actor instanceof Authenticatable ? $actor : null), 404);
        $index = app(PhpApiArtifact::class)->index();
        abort_if($index === null, 404);

        return $index;
    }
}
